<?php require 'config/db.php'; require 'includes/functions.php';
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$blood=trim($_POST['blood_group']??'');$city=trim($_POST['city']??'Dhaka');$pass=$_POST['password']??''; if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6){$error='Please provide valid details and a password of at least 6 characters.';}else{ $hash=password_hash($pass,PASSWORD_DEFAULT);$st=$conn->prepare("INSERT INTO users(name,email,phone,password,role,is_verified) VALUES(?,?,?,?, 'donor',1)");$st->bind_param('ssss',$name,$email,$phone,$hash);if($st->execute()){ $uid=$conn->insert_id;$lat=23.8103;$lng=90.4125;$d=$conn->prepare("INSERT INTO donor_profiles(user_id,blood_group,city,lat,lng,availability,response_rate,emergency_opt_in,verified) VALUES(?,?,?,?,?,'available',80,1,1)");$d->bind_param('issdd',$uid,$blood,$city,$lat,$lng);$d->execute();flash('success','Donor account created. Please log in.');header('Location: login.php');exit;}else{$error='That email is already registered.';}}}
$pageTitle='Become a Donor';include 'includes/header.php';?>
<div class="container"><div class="form-shell"><div class="form-side"><span class="kicker" style="color:#fecdd3">Join the network</span><h2>Your availability could become someone’s answer.</h2><p>Donor profiles are matched to emergencies using compatibility, availability and distance. Contact details stay out of the public request feed.</p><div class="workflow"><div class="workflow-step"><span class="step-no">✓</span><div><b>Verified profile</b><span>Blood group and readiness information</span></div></div><div class="workflow-step"><span class="step-no">⚡</span><div><b>Emergency alerts</b><span>Only relevant compatible cases</span></div></div></div></div><div class="form-main"><h2>Create donor profile</h2><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="form-row"><div class="form-group"><label>Full name</label><input class="form-control" name="name" required></div><div class="form-group"><label>Blood group</label><select class="form-control" name="blood_group" required><?php foreach(['O-','O+','A-','A+','B-','B+','AB-','AB+'] as $g):?><option><?=$g?></option><?php endforeach;?></select></div></div><div class="form-row"><div class="form-group"><label>Email</label><input class="form-control" type="email" name="email" required></div><div class="form-group"><label>Phone</label><input class="form-control" name="phone" required></div></div><div class="form-row"><div class="form-group"><label>City</label><input class="form-control" name="city" value="Dhaka" required></div><div class="form-group"><label>Password</label><input class="form-control" type="password" name="password" minlength="6" required></div></div><button class="btn btn-primary" style="width:100%">Join as verified donor</button></form></div></div></div>
